--------------------------------------------------------------------------------
-- PROJECT TITAN V13: PolarFire Clock Infrastructure
-- Module: Behavioral PLL Wrapper for Hardware-Less Development
--------------------------------------------------------------------------------
-- AMAÇ: Gerçek PolarFire donanımı olmadan sentez ve simülasyon yapabilmek için
--       davranışsal (behavioral) PLL wrapper.
--
-- GERÇEK DONANIM \u0130\u00c7\u0130N: Bu modül silinip yerine Libero "PF_CCC" (Clock
--                       Conditioning Circuitry) IP'si kullan\u0131lacak.
--
-- KOMUTAN \u015eERH\u0130: \"Donan\u0131m gelene kadar sahte PLL ile idare et. Ama PLL_LOCKED
--                 sinyalini do\u011fru ver, supervisor onu dinliyor!\"\n--------------------------------------------------------------------------------\n\nlibrary IEEE;\nuse IEEE.STD_LOGIC_1164.ALL;\n\nentity polarfire_clocking is\n    port (\n        clk_in_50mhz : in  std_logic;  -- Harici 50 MHz\n        sys_clk      : out std_logic;  -- Sistem saati (50 MHz)\n        pll_locked   : out std_logic   -- PLL kilit durumu\n    );\nend polarfire_clocking;\n\narchitecture Behavioral of polarfire_clocking is\n\n    -------------------------------------------------------------------------\n    -- Simülasyon için PLL Lock Delay\n    -------------------------------------------------------------------------\n    signal lock_delay_cnt : integer range 0 to 500000 := 0; -- ~10ms @ 50MHz\n    signal pll_locked_int : std_logic := '0';\n\nbegin\n\n    -------------------------------------------------------------------------\n    -- PASSТHROUGH CLOCK (Simülasyon/Sentez için)\n    -------------------------------------------------------------------------\n    -- Gerçek PF_CCC geldiğinde burası silinecek.\n    -- \u015eu an: Giri\u015f saati direkt ç\u0131k\u0131\u015fa geçiyor (jitter temizleme yok)\n    -------------------------------------------------------------------------\n    sys_clk <= clk_in_50mhz;\n    \n    -------------------------------------------------------------------------\n    -- PLL LOCKED SİMÜLASYONU\n    -------------------------------------------------------------------------\n    -- Gerçek PLL'ler ~10ms'de kilitlenir.\n    -- Supervisor bunu bekliyor, bu yüzden simüle ediyoruz.\n    -------------------------------------------------------------------------\n    process(clk_in_50mhz)\n    begin\n        if rising_edge(clk_in_50mhz) then\n            if lock_delay_cnt < 500000 then  -- 10ms @ 50MHz\n                lock_delay_cnt <= lock_delay_cnt + 1;\n                pll_locked_int <= '0';       -- Henüz kilitlenmedi\n            else\n                pll_locked_int <= '1';       -- Kilitlendi!\n            end if;\n        end if;\n    end process;\n    \n    pll_locked <= pll_locked_int;\n\nend Behavioral;\n\n--------------------------------------------------------------------------------\n-- TASARIM NOTLARI\n--------------------------------------------------------------------------------\n-- 1. GERÇEK PF_CCC ENTEGRASYONU (Donan\u0131m Geldi\u011finde)\n--    Libero'da:\n--      a) IP Catalog -> PolarFire Clock Conditioning Circuitry (PF_CCC)\n--      b) Input: 50 MHz, Output: 50 MHz (veya istenen frekans)\n--      c) LOCKED output'unu buradan ç\u0131kar\n--      d) Bu dosyay\u0131 sil, yerine PF_CCC instance'ini koy\n--\n--    Örnek PF_CCC instantiation:\n--    ```vhdl\n--    PF_CCC_inst : PF_CCC\n--      port map (\n--          REF_CLK_0 => clk_in_50mhz,\n--          OUT_CLK_0 => sys_clk,\n--          PLL_LOCK_0 => pll_locked\n--      );\n--    ```\n--\n-- 2. \u015eU ANK\u0130 DAVRANI\u015e (Behavioral Wrapper)\n--    -> sys_clk = clk_in_50mhz (passthrough)\n--    -> pll_locked simülasyonla ~10ms'de '1' oluyor\n--    -> Jitter temizlemeyok (gerçek PLL gerekiyor)\n--\n-- 3. SUPERVISOR ENTEGRASYONU\n--    -> system_supervisor bu pll_locked'ı bekliyor\n--    -> LOCKED='0' -> 100ms warmup başlamıyor\n--    -> Simülasyonda: 10ms lock + 100ms warmup = 110ms boot\n--\n-- 4. SENTEZ KORUMASI GEREKMEZ\n--    -> Bu modül çok basit (sadece passthrough)\n--    -> Sentezleyici hiçbir şeyi silemez\n--\n-- 5. TİMİNG\n--    -> sys_clk ile clk_in_50mhz aynı sinyal (0 delay)\n--    -> Constraint'te create_generated_clock GEREKMEZ (passthrough)\n--\n-- 6. PolarFire CCC ÖZELLİKLERİ (Referans)\n--    -> VCO range: 400 MHz - 1600 MHz\n--    -> Output jitter: <50ps RMS\n--    -> Lock time: ~5-15ms (typical)\n--    -> Power: ~10mW per CCC\n--\n-- 7. CONSTRAINT GEREKSİNİMLERİ (polarfire_constraints.pdc)\n--    ```tcl\n--    # Sadece input clock\n--    create_clock -name {clk_ext_50} -period 20 [get_ports {clk_in_50mhz}]\n--    \n--    # pll_locked asenkron\n--    set_false_path -from [get_pins {clk_inst/pll_locked_int*}]\n--    ```\n--------------------------------------------------------------------------------\n
